let reorder_success = null;
try {
    reorder_success = this.reorder_formsets();
} catch (error) {
    console.error("error", error.message);
    reorder_success = false;
}
if (!reorder_success) {
    event.preventDefault();
    return false;
}

document.addEventListener("submit", function (event) {
    if (!(event.target instanceof Element) || !event.target.closest("#" + CVModalConst.content)) {
        return;
    }
    event.preventDefault();
    cvModalSubmit(event.target, event.submitter);
});
